// The page's ground, generated by the game's rules (terrain-rules.js) and drawn as src/grim/terrain_render.py
// draws it. A quest board shows that quest's terrain; other pages roll terrain_generate_random as a save with
// every quest unlocked would. A fresh seed comes with every page load.
import { SIZE, crtRand, generate, generateRandom, questSlots } from "./terrain-rules.js";

const PATCH = 128;
const CLEAR = "rgb(63, 56, 25)";
// Layer tints: RGB 178/255 on every layer, alpha 230, 230 and 153.
const TINT_RGB = 178 / 255;
const LAYER_ALPHA = [230, 230, 153];
// DX8 alpha test after the tint: texels at or below 4/255 are discarded.
const ALPHA_REF = 4;
const UNLOCK_INDEX = 50;

function load(slot) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = `/ui/ter${slot}.png`;
  });
}

// The texture as one layer draws it: tinted, alpha test applied.
function prepare(image, alpha) {
  const canvas = document.createElement("canvas");
  canvas.width = image.width;
  canvas.height = image.height;
  const context = canvas.getContext("2d");
  context.drawImage(image, 0, 0);
  const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
  const data = pixels.data;
  for (let i = 0; i < data.length; i += 4) {
    const a = (data[i + 3] * alpha) / 255;
    data[i] *= TINT_RGB;
    data[i + 1] *= TINT_RGB;
    data[i + 2] *= TINT_RGB;
    data[i + 3] = a <= ALPHA_REF ? 0 : a;
  }
  context.putImageData(pixels, 0, 0);
  return canvas;
}

async function draw(screen) {
  const rand = crtRand(crypto.getRandomValues(new Uint32Array(1))[0]);
  const quest = screen.dataset.quest;
  const ground = quest ? generate(rand, questSlots(...quest.split(".").map(Number))) : generateRandom(rand, UNLOCK_INDEX);
  const images = await Promise.all(ground.slots.map(load));
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = SIZE;
  const context = canvas.getContext("2d");
  context.fillStyle = CLEAR;
  context.fillRect(0, 0, SIZE, SIZE);
  ground.layers.forEach((stamps, i) => {
    const texture = prepare(images[i], LAYER_ALPHA[i]);
    for (const [rotation, x, y] of stamps) {
      context.setTransform(1, 0, 0, 1, x + PATCH / 2, y + PATCH / 2);
      context.rotate(rotation);
      context.drawImage(texture, -PATCH / 2, -PATCH / 2, PATCH, PATCH);
    }
  });
  canvas.toBlob((blob) => {
    screen.style.backgroundImage = `url(${URL.createObjectURL(blob)})`;
  });
}

const screen = document.querySelector(".screen");
if (screen) draw(screen);
